//! Formatting helpers mirroring `indicators::Format`.

/// Equivalent of `std::fixed << std::setprecision(precision)` applied to
/// `value * 100`, followed by a `%` suffix.
fn format_percentage(value: f32, precision: usize) -> String {
    format!("{:.*}%", precision, value * 100.0f32)
}

/// Static formatting utilities, mirroring `indicators::Format`.
pub struct Format;

impl Format {
    /// `Format::percentage(value)` — default precision of 1 decimal place.
    pub fn percentage(value: f32) -> String {
        format_percentage(value, 1)
    }

    /// `Format::percentage(value, precision)` — explicit decimal precision.
    pub fn percentage_with_precision(value: f32, precision: usize) -> String {
        format_percentage(value, precision)
    }
}

