//! Progress primitives mirroring `indicators::ProgressBuilder` and
//! `indicators::ProgressTracker`.

use crate::indicators::format::Format;

/// Builder that produces a formatted percentage string from a
/// progress/total pair, mirroring `indicators::ProgressBuilder`.
pub struct ProgressBuilder {
    progress: u32,
    total: u32,
}

impl ProgressBuilder {
    pub fn new() -> Self {
        ProgressBuilder {
            progress: 0,
            total: 0,
        }
    }

    pub fn set_progress(&mut self, progress: u32) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: u32) -> &mut Self {
        self.total = total;
        self
    }

    /// Builds the percentage string with the default precision (1 decimal).
    pub fn build(&self) -> String {
        Format::percentage(self.ratio())
    }

    fn ratio(&self) -> f32 {
        if self.total == 0 {
            0.0
        } else {
            self.progress as f32 / self.total as f32
        }
    }
}

impl Default for ProgressBuilder {
    fn default() -> Self {
        Self::new()
    }
}

/// Named-stage progress tracker, mirroring `indicators::ProgressTracker`.
pub struct ProgressTracker {
    stages: Vec<String>,
    progress: u32,
    total: u32,
}

impl ProgressTracker {
    pub fn new() -> Self {
        ProgressTracker {
            stages: Vec::new(),
            progress: 0,
            total: 0,
        }
    }

    pub fn add_stage(&mut self, name: &str) -> &mut Self {
        self.stages.push(name.to_string());
        self
    }

    pub fn set_progress(&mut self, progress: u32) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: u32) -> &mut Self {
        self.total = total;
        self
    }

    /// Progress rendered as `"<progress>/<total>"`.
    pub fn get_progress(&self) -> String {
        format!("{}/{}", self.progress, self.total)
    }

    /// Progress rendered as a percentage with 1 decimal place.
    pub fn get_percentage(&self) -> String {
        let ratio = if self.total == 0 {
            0.0
        } else {
            self.progress as f32 / self.total as f32
        };
        Format::percentage(ratio)
    }

    /// Number of registered stages.
    pub fn stage_count(&self) -> usize {
        self.stages.len()
    }
}

impl Default for ProgressTracker {
    fn default() -> Self {
        Self::new()
    }
}

